{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Piritrexim, a lipid-soluble 2,4-diaminopyrimidine antifolate with a dimethoxybenzyl group, has an estimated oral bioavailability of ~75% in patients, supporting high F for the query's related diaminopyrimidine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Trimazosin, a 4-amino-6,7,8-trimethoxyquinazoline, shows 63% oral bioavailability in healthy men, indicating that highly methoxylated heteroaromatic diamines can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Abecarnil, a lipophilic indole-containing drug with an ester and multiple aromatic rings, has an absolute oral bioavailability of 39 ± 17% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "GSK269984A, a lipophilic chloro-substituted aromatic carboxylic acid, shows 95% absolute oral bioavailability in healthy volunteers, demonstrating that high lipophilicity and aromaticity do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Alfuzosin, a 4-amino-6,7-dimethoxyquinazoline derivative, has a mean absolute oral bioavailability of 64% in healthy volunteers, supporting high F for the query's methoxy-substituted heteroaromatic diamine system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Betrixaban, a highly aromatic, lipophilic oral anticoagulant with multiple hydrogen-bond acceptors, has an absolute oral bioavailability of 34% in humans, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pantoprazole, a heteroaromatic drug with high TPSA and multiple aromatic rings, has a mean absolute oral bioavailability of 77%, showing that such physicochemical features are compatible with high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Alisertib, a complex aromatic kinase inhibitor with methoxy, chloro, and amide functionalities, has an oral bioavailability of 0.671 (67.1%) in pediatric patients, supporting high F for the query's similarly complex aromatic scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental oral bioavailability data from structurally related heteroaromatic drugs—diaminopyrimidine/quinazoline antifolates, kinase inhibitors, and related lipophilic aromatics—are consistently above the 20% threshold, mostly in the 34–95% range. The physicochemical prior suggesting low F is outweighed by this consistent experimental evidence, although the Morgan similarities are modest and no direct query data exist.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the exact query molecule.",
    "Morgan similarities to evidence molecules are low (0.20–0.28), limiting structural transferability.",
    "No data on the query's solubility, permeability, or metabolic stability in humans.",
    "Most evidence is from human studies of related drugs, but formulation and dose effects may differ."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

